    #[test]
    fn labels_native_and_dynamic_classpath_fallbacks() {
        assert_eq!(
            fallback_label(
                "java.lang.UnsupportedOperationException",
                Some("net.minecraft.world.Level#getBlockState")
            ),
            Some("JVM fallback selected for unsupported native call: net.minecraft.world.Level#getBlockState".to_owned())
        );
        assert_eq!(
            fallback_label(
                "java.lang.ClassNotFoundException",
                Some("optional.Provider")
            ),
            Some(
                "JVM fallback selected for dynamic classpath lookup: optional.Provider".to_owned()
            )
        );
        assert_eq!(
            fallback_label("java.lang.IllegalStateException", None),
            None
        );
        assert_eq!(
            fallback_label(
                "java.lang.NoSuchMethodError",
                Some("dev.horizon.Native#missing")
            ),
            Some(
                "JVM fallback selected for missing façade member: dev.horizon.Native#missing"
                    .to_owned()
            )
        );
        assert_eq!(
            fallback_label("java.lang.NoSuchFieldError", None),
            Some("JVM fallback selected for missing façade member".to_owned())
        );
        assert_eq!(
            fallback_label(
                "java.lang.NoSuchMethodException",
                Some("net.minecraft.world.level.Level#getBlockState")
            ),
            Some(
                "JVM fallback selected for missing façade member: net.minecraft.world.level.Level#getBlockState"
                    .to_owned()
            )
        );
        assert_eq!(
            fallback_label("java.lang.NoSuchFieldException", None),
            Some("JVM fallback selected for missing façade member".to_owned())
        );
        assert_eq!(
            fallback_label(
                "java.lang.AbstractMethodError",
                Some("net.fabricmc.loader.api.ModContainer#getMetadata")
            ),
            Some(
                "JVM fallback selected for missing façade member: net.fabricmc.loader.api.ModContainer#getMetadata"
                    .to_owned()
            )
        );
        assert_eq!(
            fallback_label("java.lang.IncompatibleClassChangeError", None),
            Some("JVM fallback selected for missing façade member".to_owned())
        );
        assert_eq!(
            fallback_label(
                "java.lang.ExceptionInInitializerError",
                Some("dev.mod.RegistryBootstrap")
            ),
            Some(
                "JVM fallback selected for static initialization failure: dev.mod.RegistryBootstrap"
                    .to_owned()
            )
        );
    }

    #[test]
    fn labels_runtime_linkage_fallbacks() {
        for class in [
            "java.lang.UnsatisfiedLinkError",
            "java.lang.VerifyError",
            "java.lang.ClassFormatError",
            "java.lang.BootstrapMethodError",
            "java.lang.IllegalAccessError",
            "java.lang.InstantiationError",
        ] {
            assert_eq!(
                fallback_label(class, Some("dev.example.Mod")),
                Some(format!(
                    "JVM fallback selected for {}: dev.example.Mod",
                    if class == "java.lang.UnsatisfiedLinkError" {
                        "native linkage failure"
                    } else {
                        "runtime linkage failure"
                    }
                ))
            );
        }
    }

    #[test]
    fn maps_quilt_entrypoint_kinds_to_fabric_lifecycle_names() {
        assert_eq!(quilt_entrypoint_kind("quilt.mod.json", "main"), "init");
        assert_eq!(
            quilt_entrypoint_kind("quilt.mod.json", "client"),
            "client_init"
        );
        assert_eq!(
            quilt_entrypoint_kind("quilt.mod.json", "server"),
            "server_init"
        );
        assert_eq!(quilt_entrypoint_kind("fabric.mod.json", "main"), "main");
    }

    #[test]
    fn discovers_quilt_init_entrypoint_and_declared_kinds() {
        let path = std::env::temp_dir().join(format!(
            "horizon-jvm-quilt-{}-{}.jar",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        let file = File::create(&path).unwrap();
        let mut jar = zip::ZipWriter::new(file);
        jar.start_file("quilt.mod.json", SimpleFileOptions::default())
            .unwrap();
        jar.write_all(
            br#"{"entrypoints":{"init":"dev.example.Main","client_init":[{"value":"dev.example.Client"}]}}"#,
        )
        .unwrap();
        jar.finish().unwrap();
        assert_eq!(
            discover_entries(&path, "main").unwrap(),
            vec!["dev.example.Main"]
        );
        assert_eq!(
            discover_entries(&path, "client").unwrap(),
            vec!["dev.example.Client"]
        );
        assert_eq!(
            declared_entrypoint_kinds(&path).unwrap(),
            vec!["client_init", "init"]
        );
        let _ = std::fs::remove_file(path);
    }

